  rowBounds: Rect;
  mask: Rect;
  helper: Rect;
  sortButtonBounds: Rect;
  sortIconMatrix: SwfMatrix;
  statistics: {
    background: { bounds: Rect; stops: { ratio: number; color: number[] }[] };
